  "claims": [
    {
      "claim": "Dideoxyadenosine, a purine nucleoside, showed 38% ± 15% oral bioavailability in fasting patients, a transferable direct outcome above the 20% threshold.",
      "card_ids": ["C22"]
    },
    {
      "claim": "Emtricitabine, a polar nucleoside analog, showed 92% fasted oral bioavailability, indicating nucleoside-class molecules can achieve high F.",
      "card_ids": ["C28"]
    },
    {
      "claim": "Acyclovir, a guanine nucleoside analog, has human F of 0.2 (20%), at the threshold and not affirmatively below it.",
      "card_ids": ["C12"]
    },
    {
      "claim": "Gaultherin, a glycoside, has predicted human F of 20-30%, at or above the threshold.",
      "card_ids": ["C15"]
    },
    {
      "claim": "All transferable nucleoside and glycoside contexts report F at or above 20%; no L1 context provides affirmative evidence of F below 20%.",
      "card_ids": ["C22", "C28", "C12", "C15"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "current_gold_voting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "changed",
      "card_ids": ["C22", "C28", "C12", "C15"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for guanosine itself is supplied.",
    "The low prior rests on physicochemical descriptors (logD, TPSA, HBD/HBA), not measured absorption or first-pass data.",
    "Transfer evidence comes from other nucleosides and glycosides; guanosine-specific transporter or metabolism data are absent.",
    "Acyclovir F of 20% sits exactly at the threshold, so threshold-boundary uncertainty remains."
  ],
  "decision_summary": "Transferable nucleoside contexts (ddA 38%, emtricitabine 92%, acyclovir 20%, gaultherin 20-30%) all support F >= 20%, and no affirmative evidence supports F < 20%. The low physicochemical prior is insufficient to predict low, so the prediction is high with moderate confidence."
}

